//! Compares the Rust EIP-1559 signing hash with vectors generated by viem
//! (`scripts/gen-vectors.mjs`). Every field set must match byte for byte, both the
//! unsigned serialization and the final keccak256 hash.

use policy_vault::evm::{Address, Eip1559Tx};

fn hex_to_bytes(s: &str) -> Vec<u8> {
    let s = s.strip_prefix("0x").unwrap_or(s);
    assert!(s.len() % 2 == 0, "odd hex length: {s}");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("bad hex"))
        .collect()
}

fn to_hex(b: &[u8]) -> String {
    let mut s = String::from("0x");
    for x in b {
        s.push_str(&format!("{:02x}", x));
    }
    s
}

#[test]
fn rust_signing_hash_matches_viem() {
    let raw = include_str!("../../vectors/eip1559_signing_hash.tsv");
    let mut checked = 0;

    for line in raw.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        assert_eq!(f.len(), 11, "unexpected column count in line: {line}");
        let name = f[0];

        let to_bytes = hex_to_bytes(f[6]);
        let mut to: Address = [0u8; 20];
        to.copy_from_slice(&to_bytes);

        let tx = Eip1559Tx {
            chain_id: f[1].parse().unwrap(),
            nonce: f[2].parse().unwrap(),
            max_priority_fee_per_gas: f[3].parse().unwrap(),
            max_fee_per_gas: f[4].parse().unwrap(),
            gas_limit: f[5].parse().unwrap(),
            to,
            value: f[7].parse().unwrap(),
            data: hex_to_bytes(f[8]),
        };

        let mut preimage = vec![0x02u8];
        preimage.extend_from_slice(&tx.rlp_unsigned());
        assert_eq!(
            to_hex(&preimage),
            f[9],
            "unsigned serialization differs from viem in case {name}"
        );
        assert_eq!(
            to_hex(&tx.signing_hash()),
            f[10],
            "signing hash differs from viem in case {name}"
        );
        checked += 1;
    }

    assert!(checked >= 19, "expected at least 19 vectors, checked {checked}");
}
